macro_rules! deps {
    () => {
        PikeVM!();
        NFA!();
        StateID!();
    };
}

macro_rules! Counters {
    () => {
        deps!();
        # [doc = " A set of counters that \"instruments\" a PikeVM search. To enable this, you"] # [doc = " must enable the 'internal-instrument-pikevm' feature. Then run your Rust"] # [doc = " program with RUST_LOG=regex_automata::nfa::thompson::pikevm=trace set in"] # [doc = " the environment. The metrics collected will be dumped automatically for"] # [doc = " every search executed by the PikeVM."] # [doc = ""] # [doc = " NOTE: When 'internal-instrument-pikevm' is enabled, it will likely cause an"] # [doc = " absolute decrease in wall-clock performance, even if the 'trace' log level"] # [doc = " isn't enabled. (Although, we do try to avoid extra costs when 'trace' isn't"] # [doc = " enabled.) The main point of instrumentation is to get counts of various"] # [doc = " events that occur during the PikeVM's execution."] # [doc = ""] # [doc = " This is a somewhat hacked together collection of metrics that are useful"] # [doc = " to gather from a PikeVM search. In particular, it lets us scrutinize the"] # [doc = " performance profile of a search beyond what general purpose profiling tools"] # [doc = " give us. Namely, we orient the profiling data around the specific states of"] # [doc = " the NFA."] # [doc = ""] # [doc = " In other words, this lets us see which parts of the NFA graph are most"] # [doc = " frequently activated. This then provides direction for optimization"] # [doc = " opportunities."] # [doc = ""] # [doc = " The really sad part about this is that it absolutely clutters up the PikeVM"] # [doc = " implementation. :'( Another approach would be to just manually add this"] # [doc = " code in whenever I want this kind of profiling data, but it's complicated"] # [doc = " and tedious enough that I went with this approach... for now."] # [doc = ""] # [doc = " When instrumentation is enabled (which also turns on 'logging'), then a"] # [doc = " `Counters` is initialized for every search and `trace`'d just before the"] # [doc = " search returns to the caller."] # [doc = ""] # [doc = " Tip: When debugging performance problems with the PikeVM, it's best to try"] # [doc = " to work with an NFA that is as small as possible. Otherwise the state graph"] # [doc = " is likely to be too big to digest."] # [cfg (feature = "internal-instrument-pikevm")] # [derive (Clone , Debug)] struct Counters { # [doc = " The number of times the NFA is in a particular permutation of states."] state_sets : alloc :: collections :: BTreeMap < Vec < StateID > , u64 > , # [doc = " The number of times 'step' is called for a particular state ID (which"] # [doc = " indexes this array)."] steps : Vec < u64 > , # [doc = " The number of times an epsilon closure was computed for a state."] closures : Vec < u64 > , # [doc = " The number of times a particular state ID is pushed on to a stack while"] # [doc = " computing an epsilon closure."] stack_pushes : Vec < u64 > , # [doc = " The number of times a particular state ID is inserted into a sparse set"] # [doc = " while computing an epsilon closure."] set_inserts : Vec < u64 > , }
    };
}

Counters!();